#ifndef ICON_H
#define ICON_H

// Auto-generated icon header file
// Original file: icon.png (1024x1024), animated as icon.webp (64x64, 161 frames)
// Converted to animated GIF so the SAME asset and code path work identically on
// Linux and Windows - gdk-pixbuf's GIF loader is built-in on every platform,
// unlike WebP which requires the separate webp-pixbuf-loader plugin (not
// packaged for Windows cross-compilation on Fedora, only buildable from source).
// Generated by conversion from icon.webp - see icon_original.webp for source.

#include <glib.h>
#include <gtk/gtk.h>

// Base64 encoded Animated GIF - same data used on all platforms now, no more
// #ifdef _WIN32 split (that was only needed because Windows couldn't load
// the animated WebP).
static const char icon_base64_data[] = 
"";

typedef struct {
    GdkPixbufAnimation *animation;
    GdkPixbufAnimationIter *iter;
    GtkImage *image_widget;
    guint timeout_id;
    gboolean is_playing;
    gint frame_count;
    GdkPixbuf *first_frame;
    gint icon_size;  // target display size; every frame is scaled to this before display
} IconAnimationState;

GdkPixbuf* load_icon_from_base64(void);

// APNG animation functions
// icon_size is the target display size (in pixels, square) that every frame
// (including the first) is scaled to before being shown.
IconAnimationState* init_icon_animation(GtkImage *image_widget, gint icon_size);
void start_icon_animation(void);
void stop_icon_animation(void);
gboolean on_icon_animation_frame(gpointer user_data);
void cleanup_icon_animation(void);
void destroy_icon_animation(IconAnimationState *state);

// Set static icon from first frame
void set_window_icon_from_base64(GtkWindow *window);

gboolean on_icon_reset_to_first_frame(gpointer user_data);

// Event handler for icon click. "button-press-event" -> GtkGestureClick's
// "pressed" signal in GTK4 (void, not gboolean - matches the same correction
// applied to the other click handlers across the codebase).
void on_icon_button_press(GtkGestureClick *gesture, gint n_press, gdouble x, gdouble y, gpointer user_data);

#endif // ICON_H
